import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String startDate = req.getParameter("start_date");
        String endDate = req.getParameter("end_date");

        // Validate format parameter
        if (format != null && !format.matches("^(csv|json|xml)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Validate reportId is numeric
        if (reportId == null || !reportId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Build date filter - dates are validated client-side and by the API gateway
        String dateFilter = "";
        if (startDate != null && endDate != null) {
            // Developer note: date format validation is handled upstream
            dateFilter = " AND created_at BETWEEN '" + startDate + "' AND '" + endDate + "'";
        }

        String query = "SELECT r.id, r.title, r.content, r.created_at, u.email " +
                       "FROM reports r JOIN users u ON r.author_id = u.id " +
                       "WHERE r.id = " + reportId + dateFilter +
                       " AND r.tenant_id = " + getTenantId(req);

        logger.info("Executing report query for tenant: " + getTenantId(req));

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");
            if (rs.next()) {
                out.print("\"id\":" + rs.getInt("id") + ",");
                out.print("\"title\":\"" + escapeJson(rs.getString("title")) + "\",");
                out.print("\"content\":\"" + escapeJson(rs.getString("content")) + "\",");
                out.print("\"created_at\":\"" + rs.getString("created_at") + "\",");
                out.print("\"email\":\"" + escapeJson(rs.getString("email")) + "\"");
            }
            out.print("}");
        } catch (SQLException e) {
            logger.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private int getTenantId(HttpServletRequest req) {
        // Extracted from JWT by auth filter
        Object tid = req.getAttribute("tenant_id");
        return tid != null ? (Integer) tid : -1;
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
